def process(
    input_stream: TextIO,
    output_stream: TextIO,
    extension: str = "py",
    config: Config = DEFAULT_CONFIG,
) -> bool:
    """Parses a text stream containing unsorted import sections and sorts them alphabetically.

    The function reads from the provided `input_stream`, processes the contents to identify and sort import statements, 
    and writes the sorted results to the specified `output_stream`. It supports various configuration options through 
    the `config` parameter, including settings for line endings, additional imports to add, and file extension handling.

    Parameters:
        input_stream (TextIO): A text stream containing unsorted import sections.
        output_stream (TextIO): The target text stream where sorted import sections will be written.
        extension (str, optional): Specifies the file extension or type of script being processed. Defaults to "py", 
            but can also accept other Python-related extensions like "pyi" and "pyx".
        config (Config, optional): An instance of the `Config` class containing specific configuration settings for isort. 
            Defaults to `DEFAULT_CONFIG`.

    Returns:
        bool: A boolean value indicating whether any changes were made during the sorting process. This will be True if there 
              were modifications (e.g., due to errors or unsorted imports), and False otherwise.

    Examples:
        >>> with open('input_file.py', 'r') as input_stream, open('output_file.py', 'w') as output_stream:
        ...     made_changes = process(input_stream, output_stream)
        ... 
        >>> print("Changes were made:" if made_changes else "No changes were made.")

        In this example, the function reads from `input_file.py`, sorts its import statements, and writes the sorted content to `output_file.py`. The result is printed to indicate whether any modifications occurred during the process.
    """
    line_separator: str = config.line_ending
    add_imports: List[str] = [format_natural(addition) for addition in config.add_imports]
    import_section: str = ""
    next_import_section: str = ""
    next_cimports: bool = False
    in_quote: str = ""
    first_comment_index_start: int = -1
    first_comment_index_end: int = -1
    contains_imports: bool = False
    in_top_comment: bool = False
    first_import_section: bool = True
    indent: str = ""
    isort_off: bool = False
    code_sorting: Union[bool, str] = False
    code_sorting_section: str = ""
    code_sorting_indent: str = ""
    cimports: bool = False
    made_changes: bool = False
    stripped_line: str = ""
    end_of_file: bool = False
    verbose_output: List[str] = []

    if config.float_to_top:
        new_input = ""
        current = ""
        isort_off = False
        for line in chain(input_stream, (None,)):
            if isort_off and line is not None:
                if line == "# isort: on\n":
                    isort_off = False
                new_input += line
            elif line in ("# isort: split\n", "# isort: off\n", None) or str(line).endswith(
                "# isort: split\n"
            ):
                if line == "# isort: off\n":
                    isort_off = True
                if current:
                    if add_imports:
                        add_line_separator = line_separator or "\n"
                        current += add_line_separator + add_line_separator.join(add_imports)
                        add_imports = []
                    parsed = parse.file_contents(current, config=config)
                    verbose_output += parsed.verbose_output
                    extra_space = ""
                    while current and current[-1] == "\n":
                        extra_space += "\n"
                        current = current[:-1]
                    extra_space = extra_space.replace("\n", "", 1)
                    sorted_output = output.sorted_imports(
                        parsed, config, extension, import_type="import"
                    )
                    made_changes = made_changes or _has_changed(
                        before=current,
                        after=sorted_output,
                        line_separator=parsed.line_separator,
                        ignore_whitespace=config.ignore_whitespace,
                    )
                    new_input += sorted_output
                    new_input += extra_space
                    current = ""
                new_input += line or ""
            else:
                current += line or ""

        input_stream = StringIO(new_input)

