class FindersManager:
    _default_finders_classes: Sequence[Type[BaseFinder]] = (ForcedSeparateFinder, LocalFinder, KnownPatternFinder, PathFinder, PipfileFinder, RequirementsFinder, DefaultFinder)
    def __init__(
        self, config: Config, finder_classes: Optional[Iterable[Type[BaseFinder]]] = None
    ) -> None:
        """
        Initializes a new instance of the FindersManager class.

        This method sets up the necessary configurations and dependencies for managing finders within the system. The `config` parameter is expected to be an instance of the `Config` class, which contains all the necessary settings and parameters required for initializing the manager. This includes details such as file extensions, import sorting preferences, and other configuration options relevant to the finder operations.

        :param config: An instance of the Config class containing all necessary configurations for the FindersManager.
        :type config: Config
        """
        self.verbose: bool = config.verbose

        if finder_classes is None:
            finder_classes = self._default_finders_classes
        finders: List[BaseFinder] = []
        for finder_cls in finder_classes:
            try:
                finders.append(finder_cls(config))
            except Exception as exception:
                # if one finder fails to instantiate isort can continue using the rest
                if self.verbose:
                    print(
                        (
                            f"{finder_cls.__name__} encountered an error ({exception}) during "
                            "instantiation and cannot be used"
                        )
                    )
